17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
32	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidAddressException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.util.Households;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
66	     * new owner's id, its assigned {@code customerCode} and its {@code registrationDate}.
67	     */
68	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
119	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
120	        if (registrationDate == null) {
121	            registrationDate = java.time.LocalDate.now();
122	        }
123	        registrationDate = toBusinessDay(registrationDate);
124	        owner.setRegistrationDate(registrationDate);
125	        rejectDailyLimitReached(registrationDate);
126	        rejectCityAtCapacity(owner.getCity());
127	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
128	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
129	        }
130	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
131	        rejectDuplicateTelephone(telephone);
132	        owner.setTelephone(telephone);
133	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
134	        owner.setCustomerCode(assignCustomerCode(owner.getCity(), owner.getLastName()));
135	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
136	        this.clinicService.saveOwner(owner);
137	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
138	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
139	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
140	        headers.setLocation(UriComponentsBuilder.newInstance()
141	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
142	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
143	    }
144	
145	    /**
146	     * The maximum number of owners that may be created in a single day. Creating an owner once this
147	     * many owners already carry today's {@code registrationDate} is rejected.
148	     */
149	    private static final int DAILY_OWNER_LIMIT = 100;
150	
151	    /**
152	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
153	     * given business day as their {@code registrationDate}. The count is keyed by the
154	     * business-day-adjusted registration date of the owner being created (see
155	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
156	     * with no {@code registrationDate} are ignored.
157	     *
158	     * @param registrationDate the business-day-adjusted registration date of the owner being created
159	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
160	     */
161	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
162	        long count = this.clinicService.findAllOwners().stream()
163	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
164	            .count();
165	        if (count >= DAILY_OWNER_LIMIT) {
166	            throw new DailyOwnerLimitException(registrationDate);
167	        }
168	    }
169	
170	    /**
171	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is moved forward to
172	     * the following Monday; a weekday is returned unchanged. This applies to the effective
173	     * registration date whether it was supplied in the request or defaulted to the server date, and
174	     * every value derived from the registration date uses the adjusted result.
175	     *
176	     * @param date the effective registration date
177	     * @return {@code date} itself when it is a weekday, otherwise the following Monday
178	     */
179	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
180	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
181	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
182	            date = date.plusDays(1);
183	        }
184	        return date;
185	    }
186	
187	    /**
188	     * The maximum number of owners a single city may contain. Creating an owner in a city that
189	     * already holds this many owners is rejected.
190	     */
191	    private static final int CITY_CAPACITY = 50;
192	
193	    /**
194	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
195	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
196	     * treated as empty), the same way {@link #assignCustomerCode} counts a city's owners.
197	     *
198	     * @param city the city of the owner being created
199	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
200	     */
201	    private void rejectCityAtCapacity(String city) {
202	        String cityValue = city == null ? "" : city;
203	        long count = this.clinicService.findAllOwners().stream()
204	            .filter(existing -> cityValue.equalsIgnoreCase(
205	                existing.getCity() == null ? "" : existing.getCity()))
206	            .count();
207	        if (count >= CITY_CAPACITY) {
208	            throw new CityAtCapacityException(city);
209	        }
210	    }
211	
212	    /**
213	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
214	     * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
215	     * three letters of the last name and NNNN a per-city 4-digit zero-padded sequence equal to one
216	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
217	     *
218	     * @param city the owner's city
219	     * @param lastName the owner's last name
220	     * @return the assigned customer code
221	     */
222	    private String assignCustomerCode(String city, String lastName) {
223	        String city3 = prefix3(city);
224	        String last3 = prefix3(lastName);
225	        String cityValue = city == null ? "" : city;
226	        int sequence = (int) this.clinicService.findAllOwners().stream()
227	            .filter(existing -> cityValue.equalsIgnoreCase(
228	                existing.getCity() == null ? "" : existing.getCity()))
229	            .count() + 1;
230	        return String.format("%s-%s-%04d", city3, last3, sequence);
231	    }
232	
233	    /**
234	     * Returns the upper-cased first three letters of the given value, or fewer if the value is
235	     * shorter, treating {@code null} as empty.
236	     */
237	    private String prefix3(String value) {
238	        String name = value == null ? "" : value;
239	        return name.substring(0, Math.min(3, name.length()))
240	            .toUpperCase(java.util.Locale.ROOT);
241	    }
242	
243	    /**
244	     * Counts how many existing owners share the given first and last name, compared
245	     * case-insensitively, at the time this owner is created. The value excludes the owner
246	     * being created (which has not yet been saved) and is stored on the new owner and returned
247	     * as its {@code namesakeCount}.
248	     *
249	     * @param firstName the first name of the owner being created
250	     * @param lastName the last name of the owner being created
251	     * @return the number of existing owners with the same first and last name
252	     */
253	    private int countNamesakes(String firstName, String lastName) {
254	        String first = firstName == null ? "" : firstName;
255	        String last = lastName == null ? "" : lastName;
256	        return (int) this.clinicService.findAllOwners().stream()
257	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
258	                && last.equalsIgnoreCase(existing.getLastName()))
259	            .count();
260	    }
261	
262	    /**
263	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
264	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
265	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
266	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
267	     * {@code "+61412345678"}. The E.164 value is stored and returned.
268	     *
269	     * @param telephone the raw telephone as submitted
270	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
271	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
272	     */
273	    private String normalizeTelephone(String telephone) {
274	        String raw = telephone == null ? "" : telephone.trim();
275	        boolean hasCountryCode = raw.startsWith("+");
276	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
277	        if (hasCountryCode) {
278	            cleaned = cleaned.substring(1);
279	        }
280	        String digits;
281	        if (hasCountryCode) {
282	            digits = cleaned;
283	        } else {
284	            if (cleaned.startsWith("0")) {
285	                cleaned = cleaned.substring(1);
286	            }
287	            digits = "61" + cleaned;
288	        }
289	        if (!digits.matches("[0-9]{8,15}")) {
290	            throw new InvalidTelephoneException(telephone);
291	        }
292	        return "+" + digits;
293	    }
294	
295	    /**
296	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
297	     * multi-character top-level label. Deliberately lenient about the exact character set while still
298	     * rejecting values that are clearly not addresses (e.g. missing '@').
299	     */
300	    private static final java.util.regex.Pattern EMAIL_PATTERN =
301	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
302	
303	    /**
304	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
305	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
306	     * lower-cased before being stored and returned.
307	     *
308	     * @param email the raw email as submitted, may be {@code null}
309	     * @return the lower-cased email, or {@code null} when none was supplied
310	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
311	     */
312	    private String normalizeEmail(String email) {
313	        if (email == null || email.isBlank()) {
314	            return null;
315	        }
316	        String trimmed = email.trim();
317	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
318	            throw new InvalidEmailException(email);
319	        }
320	        return trimmed.toLowerCase(java.util.Locale.ROOT);
321	    }
322	
323	    /**
324	     * Common street-type abbreviations expanded to their full word during address normalization.
325	     */
326	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
327	        "ST", "STREET",
328	        "RD", "ROAD",
329	        "AVE", "AVENUE");
330	
331	    /**
332	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
333	     * whitespace collapse to a single space, the value is upper-cased and common street-type
334	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
335	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
336	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
337	     * for every address comparison (household duplicate detection and the shared household id).
338	     *
339	     * @param address the raw address as submitted
340	     * @return the normalized address
341	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
342	     */
343	    private String normalizeAddress(String address) {
344	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
345	        if (collapsed.isEmpty()) {
346	            throw new InvalidAddressException(address);
347	        }
348	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
349	        StringBuilder normalized = new StringBuilder(collapsed.length());
350	        for (int i = 0; i < tokens.length; i++) {
351	            if (i > 0) {
352	                normalized.append(' ');
353	            }
354	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
355	        }
356	        return normalized.toString();
357	    }
358	
359	    /**
360	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
361	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
362	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
363	     * {@code "+61 412 345 678"}) are still treated as duplicates.
364	     *
365	     * @param telephone the E.164 telephone of the owner being created
366	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
367	     */
368	    private void rejectDuplicateTelephone(String telephone) {
369	        boolean duplicate = this.clinicService.findAllOwners().stream()
370	            .map(Owner::getTelephone)
371	            .filter(existing -> existing != null)
372	            .map(this::toE164OrNull)
373	            .filter(existing -> existing != null)
374	            .anyMatch(telephone::equals);
375	        if (duplicate) {
376	            throw new DuplicateTelephoneException(telephone);
377	        }
378	    }
379	
380	    /**
381	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
382	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number.
383	     */
384	    private String toE164OrNull(String telephone) {
385	        try {
386	            return normalizeTelephone(telephone);
387	        } catch (InvalidTelephoneException e) {
388	            return null;
389	        }
390	    }
391	
392	    /**
393	     * Rejects creating an owner who shares a household with an existing owner, i.e. another owner
394	     * already has the same last name and the same address. Last names are compared case-insensitively
395	     * with whitespace collapsed; addresses are compared in their normalized form (see
396	     * {@link #normalizeAddress}, which every owner's stored address already uses), so values that
397	     * differ only in letter case, spacing or a common street-type abbreviation still count as a match.
398	     * This check is skipped when the request sets {@code sharesHousehold} to {@code true}.
399	     *
400	     * @param lastName the last name of the owner being created
401	     * @param address the normalized address of the owner being created
402	     * @throws DuplicateHouseholdException (409 Conflict) if another owner shares this household
403	     */
404	    private void rejectDuplicateHousehold(String lastName, String address) {
405	        String normalizedLastName = Households.normalize(lastName);
406	        String normalizedAddress = Households.normalize(address);
407	        boolean duplicate = this.clinicService.findAllOwners().stream()
408	            .anyMatch(existing ->
409	                Households.normalize(existing.getLastName()).equals(normalizedLastName)
410	                    && Households.normalize(existing.getAddress()).equals(normalizedAddress));
411	        if (duplicate) {
412	            throw new DuplicateHouseholdException(lastName, address);
413	        }
414	    }
415	
416	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
417	    @Override
418	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
419	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
420	        if (currentOwner == null) {
421	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
422	        }
423	        currentOwner.setAddress(ownerFieldsDto.getAddress());
424	        currentOwner.setCity(ownerFieldsDto.getCity());
425	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
426	        currentOwner.setLastName(ownerFieldsDto.getLastName());
427	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
428	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
429	        this.clinicService.saveOwner(currentOwner);
430	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
431	    }
432	
433	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
434	    @Transactional
435	    @Override
436	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
437	        Owner owner = this.clinicService.findOwnerById(ownerId);
438	        if (owner == null) {
439	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
440	        }
441	        this.clinicService.deleteOwner(owner);
442	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
443	    }
444	
445	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
446	    @Override
447	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
448	        Owner owner = this.clinicService.findOwnerById(ownerId);
449	        if (owner == null) {
450	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
451	        }
452	        HttpHeaders headers = new HttpHeaders();
453	        Pet pet = petMapper.toPet(petFieldsDto);
454	        owner.setId(ownerId);
455	        pet.setOwner(owner);
456	        pet.getType().setName(null);
457	        this.clinicService.savePet(pet);
458	        PetDto petDto = petMapper.toPetDto(pet);
459	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
460	            .buildAndExpand(pet.getId()).toUri());
461	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
462	    }
463	
464	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
465	    @Override
466	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
467	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
468	        if (currentOwner != null) {
469	            Pet currentPet = this.clinicService.findPetById(petId);
470	            if (currentPet != null) {
471	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
472	                currentPet.setName(petFieldsDto.getName());
473	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
474	                this.clinicService.savePet(currentPet);
475	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
476	            }
477	        }
478	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
479	    }
480	
481	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
482	    @Override
483	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
484	        HttpHeaders headers = new HttpHeaders();
485	        Visit visit = visitMapper.toVisit(visitFieldsDto);
486	        Pet pet = new Pet();
487	        pet.setId(petId);
488	        visit.setPet(pet);
489	        this.clinicService.saveVisit(visit);
490	        VisitDto visitDto = visitMapper.toVisitDto(visit);
491	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
492	            .buildAndExpand(visit.getId()).toUri());
493	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
494	    }
495	
496	
497	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
498	    @Override
